; AnalysisDetectorInitTables / SkoolDraftAlign: a 256-byte table on a page boundary read as LD H,page / LD L,A /
; LD A,(HL); its content follows x*8 (as loaded). The draft writes ALIGN 256 before it and LD H,table/256.
        org $8000
start:
        ld sp,$9F00
        di
main:
        ld a,(index)
        inc a
        ld (index),a
        ld l,a
        ld h,table/256
        ld a,(hl)
        ld (out),a
        jr main
index:  db 0
out:    db 0
        ds $8100-$
